 998	        let formatter = MarkdownFormatter::default();
 999	        let source = "#!liminal-explicit-v1\nnode paragraph {\n  literal \"a\";\n}\n";
1000	        let document = formatter.parse(source).expect("parses");
1001	
1002	        // The fixture must be compact-representable AS PARSED, or the two
1003	        // assertions below would pass against a document refused for some
1004	        // unrelated reason.
1005	        assert_eq!(
1006	            emit_compact(&document.hir).as_deref(),
1007	            Some("a\n"),
1008	            "the bare fixture must be compact-representable, or this test proves nothing"
1009	        );
1010	
1011	        let literal_index = document
1012	            .hir
1013	            .items
1014	            .iter()
1015	            .position(|item| matches!(item.kind, HirItemKind::Literal { .. }))
1016	            .expect("the fixture has a literal");
1017	
1018	        let mut carries_attributes = document.hir.clone();
1019	        carries_attributes.items[literal_index]
1020	            .attributes
1021	            .insert("id".into(), HirValue::String("i".into()));
1022	        assert_eq!(
1023	            emit_compact(&carries_attributes),
1024	            None,
1025	            "a literal carrying attributes has no compact spelling; emitting one drops them"
1026	        );
1027	
1028	        let mut carries_children = document.hir.clone();
1029	        let borrowed = document.hir.roots[0];
1030	        carries_children.items[literal_index]
1031	            .children
1032	            .push(borrowed);
1033	        assert_eq!(
1034	            emit_compact(&carries_children),
1035	            None,
1036	            "a literal with children has no compact spelling; emitting one drops them"
1037	        );
1038	    }
