 102	/// An unelaborated region left as a stub by the coarse structural scan
 103	/// (verbatim from the v4 §22 sketch).
 104	///
 105	/// Unneeded regions remain opaque: only their exact byte range, content hash,
 106	/// and coarse classification are known until demand-driven parsing (v4 §23)
 107	/// elaborates them because they are visible, edited, queried, referenced,
 108	/// required by a pass, or needed by a backend.
 109	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
 110	pub struct OpaqueBlock {
 111	    /// Exact byte range of the block within its source basis (v4 §22).
 112	    pub range: SourceRange,
 113	    /// Content hash of the raw bytes, for structural sharing and change
 114	    /// detection across revisions (v4 §9, §22).
 115	    pub hash: ContentHash,
 116	    /// Cheap classification produced by the coarse scan (v4 §22).
 117	    pub coarse_kind: CoarseKind,
 118	}
