 313	fn verify_oracle_independence(root: &Utf8Path) -> Result<()> {
 314	    for (file, function, forbidden) in INDEPENDENT_ORACLES {
 315	        let path = root.join(file);
 316	        anyhow::ensure!(
 317	            path.is_file(),
 318	            "{file}: independent oracle {function} has no source file"
 319	        );
 320	        // The scanned body spans the crate, so the aliases must too: a `use`
 321	        // that renames a forbidden symbol in another module renames it for
 322	        // code that is now inside the body being judged.
 323	        let text = crate_sources(root, file)?;
 324	        // Blind pass 1 at aecb2ec7 (A10): only the oracle's own body was
 325	        // scanned, so `fn helper(x) { paragraph::parse(x) }` called from the
 326	        // oracle reached the production path through one hop and named
 327	        // nothing. The body is the transitive closure now: the oracle plus
 328	        // every function defined in the same file that it reaches.
 329	        anyhow::ensure!(
 330	            item_body(&text, function).is_some(),
 331	            "{file}: independent oracle {function} is not defined"
 332	        );
 333	        let body = oracle_reachable_body(&text, function);
 334	        // Blind pass 1 at aa00d41 (A02): the scan matched literal paths, so
 335	        // `use liminal_source::paragraph::parse as p; p(input)` named none of
 336	        // them. A `use` that renames a forbidden symbol makes its alias
 337	        // forbidden too, in this file.
 338	        let mut watched_words: Vec<String> = Vec::new();
 339	        let mut watched = forbidden
 340	            .iter()
 341	            .map(|s| (*s).to_owned())
 342	            .collect::<Vec<_>>();
 343	        for line in text.lines() {
 344	            for (symbol, alias) in use_aliases(line) {
 345	                if forbidden.iter().any(|watch| {
 346	                    watch.contains(&symbol) || symbol.contains(watch.trim_end_matches('('))
 347	                }) {
 348	                    // Blind pass 1 at 5fb1b57 (A02): only the call form was
 349	                    // watched, so `use ...::paragraph as prod;` followed by
 350	                    // `prod::parse(input)` named nothing. A module alias is
 351	                    // used with `::`, a function alias with `(`.
 352	                    watched.push(format!("{alias}("));
 353	                    watched.push(format!("{alias}::"));
 354	                    // Blind pass 1 at `aeed70f9` (A02): only the call and
 355	                    // module forms were watched, so `let q = p; q(input)`
 356	                    // reached the production path under a name the scan had
 357	                    // never heard of. The bare alias is watched as a WORD, so
 358	                    // handing it to anything at all is the signal.
 359	                    watched_words.push(alias);
 360	                }
 361	            }
 362	        }
 363	        for symbol in &watched {
 364	            anyhow::ensure!(
 365	                !body.contains(symbol.as_str()),
 366	                "{file}: oracle {function} reaches the production path it judges ({symbol}); \
 367	                 ADR-0020 §5 requires an independent oracle"
 368	            );
 369	        }
 370	        for word in &watched_words {
 371	            anyhow::ensure!(
 372	                !mentions_word(&body, word),
 373	                "{file}: oracle {function} names the aliased production path it judges \
 374	                 ({word}); ADR-0020 §5 requires an independent oracle"
 375	            );
 376	        }
 377	    }
 378	    Ok(())
 379	}
