 382	/// status tuple and the packet digest, never the table cells the flip renders
 383	/// from artifacts. Each pass block's rows are re-derived from the committed
 384	/// record and compared; an unqualified packet's rows must all be NOT_RUN.
 385	/// The eleven cells the flip renders for one pass block, derived from its
 386	/// record exactly as `haqp_flip_packet.py` derives them.
 387	fn expected_review_rows(record: &ReviewRecord) -> [(&'static str, String); 11] {
 388	    let caught = record
 389	        .attempts
 390	        .iter()
 500	    "| Surface | Primary implementation |",
