 504	/// A cell that asserts nothing: the lane has not run, or the surface is
 505	/// quarantined behind Phase 1 authorization (AM-17.2).
 506	fn cell_claims_nothing(cell: &str) -> bool {
 507	    let cell = cell.trim();
 508	    // `NOT_RUN — prohibited` and `QUARANTINED (AM-17.2)` carry a reason after
 509	    // the marker, so the marker is a prefix. A reason may not smuggle a
 510	    // verdict past the whole-cell check below (review of `a5c27fc`).
 511	    let annotated = (cell.starts_with("NOT_RUN ") || cell.starts_with("QUARANTINED"))
 512	        && !cell
 513	            .split(|ch: char| !ch.is_ascii_alphabetic())
 514	            .any(|word| VERDICT_VOCABULARY.contains(&word.to_ascii_lowercase().as_str()));
 515	    cell.is_empty()
 516	        || cell == "NOT_RUN"
 517	        || annotated
 518	        || cell.chars().all(|ch| ch == '-' || ch == ':')
 519	}
