 749	/// Verify this repository's HAQP state for the named subcommand.
 750	pub fn verify_inventory_repo(root: &Utf8Path) -> Result<()> {
 751	    let packet = read_packet(root)?;
 752	    verify_packet_shape(&packet)?;
 753	    verify_requirement_sources(root, &packet)?;
 754	    verify_packet_statuses(&packet, inventory_statuses())?;
 755	    verify_markdown_surface(root, &packet)?;
 756	    verify_markdown_review_blocks(root, &packet)?;
 757	    verify_markdown_tables(root, &packet)?;
 758	    verify_oracle_independence(root)?;
 759	    // M17.5 F-65: the mutation plan's gates lived only in the qualified path,
 760	    // which runs after the flip. A plan defect therefore cost a whole lane to
 761	    // discover, and `haq verify-inventory` — the command run by hand between
 762	    // lanes — never read the plan at all. AM-17.10's derivation and F-64's
 763	    // operator contract are checks on the PACKET, so they belong here too.
 764	    verify_mutant_source_coordinates(root, &packet)?;
 765	    verify_mutant_anchors_support_operators(root, &packet)?;
 766	    verify_mutant_killing_tests(root, &packet)?;
 767	    // Blind pass 2 at `ec045588` (A05, A09, A12): four checks were reachable
 768	    // only through `verify_qualified_repo`, which refuses before it starts
 769	    // unless the packet is already qualified — so at stage 1a they had never
 770	    // run against anything, and replacing each with `Ok(())` changed no
 771	    // verdict. F-65 moved the mutation plan's gates here; these are the rest
 772	    // that need no provenance, which is to say everything whose evidence is
 773	    // already in the tree.
 774	    verify_qualification_stage(&packet)?;
 775	    verify_locked_corpus_has_no_aliases(root)?;
 776	    verify_crash_terminal_states(&read_crash_evidence(root)?)?;
 777	    verify_review_receipts_inventory(root, &packet)?;
 778	    Ok(())
 779	}
