1232	/// generator actually writes — was gitignored and therefore unreadable.
1233	fn verify_generated_evidence(root: &Utf8Path, packet: &Packet) -> Result<()> {
1234	    let path = root.join("conformance/haqp/evidence/generated.json");
1235	    let bytes = fs::read(&path).with_context(|| {
1236	        format!("{path}: committed generated evidence is required; run `just haq-generated`")
1237	    })?;
