1239	        serde_json::from_slice(&bytes).with_context(|| format!("parse {path}"))?;
1240	    require_eq(
1241	        "generated evidence schema_version",
1242	        &recorded.schema_version,
1243	        "haqp-generated-v3-negative-categories",
1244	    )?;
1245	    require_eq(
1246	        "generated evidence artifact_blake3",
1247	        &recorded.artifact_blake3,
1248	        &generated_artifact_digest(&recorded.rows)?,
1249	    )?;
1250	    require_exact_ids(
