2591	fn verify_cross_pass_reproduction(records: &[(String, ReviewRecord)]) -> Result<()> {
2592	    if records.is_empty() {
2593	        return Ok(());
2594	    }
2595	    anyhow::ensure!(
2596	        records.len() == 2,
2597	        "cross-pass reproduction requires two records"
2598	    );
2599	    // Every attempt both passes made, which is what says whether a shared word
2600	    // is rare or is something the campaign writes everywhere (A09).
2601	    let corpus: Vec<&ReviewRecordAttempt> = records
2602	        .iter()
2603	        .flat_map(|(_, record)| record.attempts.iter())
2604	        .collect();
2605	    for (index, (who, record)) in records.iter().enumerate() {
2606	        let other = &records[1 - index].1;
2607	        let findings = review_finding_ids(&record.findings, &record.attempts, who)?;
2608	        for finding_id in &record.independently_reproduced {
2609	            let attempt_id = findings.get(finding_id.as_str()).with_context(|| {
2610	                format!("{who}: reproduced finding {finding_id:?} is not linked")
2611	            })?;
2612	            let attempt = record
2613	                .attempts
2614	                .iter()
2615	                .find(|attempt| attempt.id == *attempt_id)
2616	                .expect("finding linkage validated");
2617	            let matches = other
2618	                .attempts
2619	                .iter()
2620	                .filter(|candidate| {
2621	                    candidate.classification == "verified_defect"
2622	                        && candidate.independently_reproduced
2623	                        && candidate.attack_class == attempt.attack_class
2624	                        && candidate.target == attempt.target
2625	                        && reports_the_same_defect(candidate, attempt, &corpus)
2626	                })
2627	                .count();
2628	            anyhow::ensure!(
2629	                matches == 1,
2630	                "{who}: reproduced finding {finding_id:?} needs exactly one independently reproduced defect in the other pass with the same attack class, the same source coordinate, and a report about the same defect; found {matches}"
2631	            );
2632	        }
2633	    }
2634	    Ok(())
2635	}
