 521	/// The rows of the table whose header starts with `header`, each split into
 522	/// trimmed cells. The separator row is dropped.
 523	/// Every table under `header`, with the width its own header line declares.
 524	/// Blind pass 1 at `6b36bbb9` (A03): this found the FIRST header and stopped,
 525	/// so a second table spelling the same header was never read — its rows could
 526	/// claim anything. A document may render a header more than once, so all of
 527	/// them are returned and each is judged against its own header's width.
 528	fn markdown_tables<'a>(text: &'a str, header: &str) -> Vec<(usize, Vec<Vec<&'a str>>)> {
 529	    let mut tables = Vec::new();
 530	    for (offset, _) in text.match_indices(header) {
 531	        let is_line_start = text[..offset]
 532	            .chars()
 533	            .next_back()
 534	            .is_none_or(|previous| previous == '\n');
 535	        if !is_line_start {
 536	            continue;
 537	        }
 538	        let mut lines = text[offset..].lines();
 539	        let width = lines
 540	            .next()
 541	            .map(|line| line.trim().trim_matches('|').split('|').count())
 542	            .unwrap_or_default();
 543	        let mut rows = Vec::new();
 544	        for line in lines {
 545	            if !line.starts_with('|') {
 546	                break;
 547	            }
 548	            let cells = line
 549	                .trim_matches('|')
 550	                .split('|')
 551	                .map(str::trim)
 552	                .collect::<Vec<_>>();
 553	            if cells
 554	                .iter()
 555	                .all(|cell| cell.chars().all(|ch| ch == '-' || ch == ':'))
 556	            {
 557	                continue;
 558	            }
 559	            rows.push(cells);
 560	        }
 561	        tables.push((width, rows));
 562	    }
 563	    tables
 564	}
