 566	/// While the packet is unqualified, a rendered table may carry only what the
 567	/// PACKET already declares — family names, predeclared counts, the declared
 568	/// fuzz budget — and otherwise must claim nothing. The flip is the only thing
 569	/// that may write a result, and it runs only on a qualified packet, so any
 570	/// other value in these tables is drift (A09).
 571	fn verify_markdown_tables(root: &Utf8Path, packet: &Packet) -> Result<()> {
 572	    let path = root.join("docs/execution/phase1-suite-review.md");
 573	    let text = fs::read_to_string(&path).with_context(|| format!("read {path}"))?;
 574	    // Blind pass 1 at ee646f8c (A09): this returned here for any qualified
 575	    // packet, on the reasoning that "the rest are bound by the packet digest
 576	    // this markdown carries". They are not. The digest binds the packet;
 577	    // editing a cell of this markdown leaves it untouched, so every table
 578	    // outside the review blocks went unchecked the moment provenance existed.
 579	    // Qualification changes exactly one thing: the flip may write results. So
 580	    // the shapes are checked either way, and only the value rule relaxes.
 581	    let qualified = packet.provenance.is_some();
 582	    let mut declared = BTreeSet::new();
 583	    for mutant in &packet.mutants {
 584	        declared.insert(mutant.family.clone());
 585	    }
 586	    for row in &packet.generated {
 587	        declared.insert(row.family.clone());
 588	        declared.insert(row.accepted.to_string());
 589	    }
 590	    let mut by_family = BTreeMap::<&str, usize>::new();
 591	    for mutant in &packet.mutants {
 592	        *by_family.entry(mutant.family.as_str()).or_default() += 1;
 593	    }
 594	    for count in by_family.values() {
 595	        declared.insert(count.to_string());
 596	    }
 597	    // The declared per-family fuzz budget, as the markdown spells it. ADR-0020
 598	    // §4 fixes 30 minutes per family; the packet names the targets, and the
 599	    // minutes are derived from the campaign, so the constant is the ADR's.
 600	    declared.insert("30 minutes".to_owned());
 601	    // The packet carries no `activation` field, so the markdown's activation
 602	    // column is editorial. It is a CLOSED vocabulary rather than free text: a
 603	    // new value is a visible decision, not drift.
 604	    for activation in ACTIVATION_VOCABULARY {
 605	        declared.insert((*activation).to_owned());
 606	    }
 607	    for requirement in &packet.requirements {
 608	        declared.insert(requirement.id.clone());
 609	    }
 610	    for test in &packet.tests {
 611	        declared.insert(test.id.clone());
 612	        declared.insert(test.name.clone());
 613	    }
 614	    // No cell in ANY table may be a verdict while the packet is unqualified.
 615	    let lines = text.lines().collect::<Vec<_>>();
 616	    for (index, line) in lines.iter().enumerate() {
 617	        let trimmed = line.trim();
 618	        if !trimmed.starts_with('|') {
 619	            continue;
 620	        }
 621	        // A header row names its columns — "Executed", "Killed", "Survived"
 622	        // are column NAMES there, not claims. A header is the row a separator
 623	        // follows.
 624	        let is_header = lines.get(index + 1).is_some_and(|next| {
 625	            let next = next.trim();
 626	            next.starts_with('|')
 627	                && next
 628	                    .trim_matches('|')
 629	                    .chars()
 630	                    .all(|ch| matches!(ch, '-' | ':' | '|' | ' '))
 631	        });
 632	        if is_header {
 633	            continue;
 634	        }
 635	        for cell in trimmed.trim_matches('|').split('|') {
 636	            let value = cell.trim().trim_matches('`').trim().to_ascii_lowercase();
 637	            // A cell IS a verdict, or annotates a marker with one: both
 638	            // `| pass |` and `| NOT_RUN — passed |` claim a result the lane
 639	            // has not recorded (review of `a5c27fc`).
 640	            let smuggled = (value.starts_with("not_run") || value.starts_with("quarantined"))
 641	                && value
 642	                    .split(|ch: char| !ch.is_ascii_alphabetic())
 643	                    .any(|word| VERDICT_VOCABULARY.contains(&word));
 644	            anyhow::ensure!(
 645	                qualified || (!VERDICT_VOCABULARY.contains(&value.as_str()) && !smuggled),
 646	                "review markdown claims {value:?} while the packet is unqualified; only the \
 647	                 flip may write a verdict, and it runs on a qualified packet"
 648	            );
 649	        }
 650	    }
 651	    for header in RENDERED_TABLES {
 652	        let tables = markdown_tables(&text, header);
 653	        anyhow::ensure!(
 654	            !tables.is_empty(),
 655	            "review markdown has no table {header:?}"
 656	        );
 657	        // The HEADER's width, not the first row's: the finding was a row with
 658	        // surplus cells beneath a narrower header, which comparing rows to
 659	        // each other would not see. Each table brings its own.
 660	        for (width, rows) in tables {
 661	            for row in rows {
 662	                // Blind pass 1 at 9eca4f0 (A09): cell VALUES were checked but not
 663	                // how many there were, so a row could carry surplus cells beneath
