2647	/// The reviewer's raw answer lives beside its record as `<record>.raw.txt`;
2648	/// its SHA-256 must be the record's `raw_response_sha256` (A09).
2649	fn verify_review_raw_response(
2650	    root: &Utf8Path,
2651	    record_path: &Utf8Path,
2652	    expected: &str,
2653	) -> Result<()> {
2654	    let raw_path = record_path.with_extension("raw.txt");
2655	    let relative = raw_path.strip_prefix(root).unwrap_or(&raw_path);
