2701	fn rulings(root: &Utf8Path) -> Result<Vec<Ruling>> {
2702	    let dir = root.join("docs/execution/rulings");
2703	    if !dir.is_dir() {
2704	        return Ok(Vec::new());
2705	    }
2706	    let mut files = fs::read_dir(dir.as_std_path())?
2707	        .map(|entry| entry.map(|e| e.path()))
2708	        .collect::<std::io::Result<Vec<_>>>()?;
2709	    files.sort();
2710	    let mut out = Vec::new();
2711	    for file in files {
2712	        let file = Utf8PathBuf::from_path_buf(file)
2713	            .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
2714	        if file.extension() != Some("md") {
2715	            continue;
2716	        }
2717	        let text = fs::read_to_string(&file)?;
2718	        let front = text
2719	            .strip_prefix("---\n")
2720	            .and_then(|rest| rest.split_once("\n---\n"))
2721	            .map(|(front, _)| front)
2722	            .with_context(|| format!("{file}: ruling has no front matter"))?;
2723	        let field = |key: &str| -> Result<String> {
2724	            front
2725	                .lines()
2726	                .find_map(|line| line.strip_prefix(&format!("{key}: ")))
2727	                .map(|v| v.trim().trim_matches('"').to_owned())
2728	                .with_context(|| format!("{file}: ruling front matter lacks {key}"))
2729	        };
2730	        let excludes = field("claim_excludes").unwrap_or_default();
2731	        let requires = field("claim_requires")?;
2732	        anyhow::ensure!(
2733	            !requires.trim().is_empty(),
2734	            "{file}: ruling claim_requires is empty; a ruling that answers any claim in its \
2735	             class and file clears defects it was never shown (A08)"
2736	        );
2737	        out.push(Ruling {
2738	            id: field("id")?,
2739	            attack_class: field("attack_class")?,
2740	            target: field("target")?,
2741	            claim_requires: requires
2742	                .split(';')
2743	                .map(|phrase| phrase.trim().to_ascii_lowercase())
2744	                .filter(|phrase| !phrase.is_empty())
2745	                .collect(),
2746	            claim_excludes: excludes
2747	                .split(';')
2748	                .map(|phrase| phrase.trim().to_ascii_lowercase())
2749	                .filter(|phrase| !phrase.is_empty())
2750	                .collect(),
2751	            status: field("status")?,
2752	            file: file.strip_prefix(root).unwrap_or(&file).to_string(),
2753	        });
2754	    }
2755	    Ok(out)
2756	}
