2758	/// A ruling is in force when its status is `ruled` and the last commit that
2759	/// touched its file verifies against the pinned signers. A draft, an
2760	/// uncommitted edit, or an unsigned commit clears nothing.
2761	fn ruling_in_force(root: &Utf8Path, ruling: &Ruling) -> Result<bool> {
2762	    if ruling.status != "ruled" {
2763	        return Ok(false);
2764	    }
2765	    let signers = root.join(RULING_SIGNERS);
2766	    anyhow::ensure!(
2767	        signers.is_file(),
2768	        "{RULING_SIGNERS} is missing; a ruling cannot be verified against no signer"
2769	    );
2770	    let dirty = git_text(root, &["status", "--porcelain", "--", &ruling.file])?;
2771	    if !dirty.trim().is_empty() {
2772	        return Ok(false);
2773	    }
2774	    let commit = git_text(root, &["log", "-1", "--format=%H", "--", &ruling.file])?;
2775	    if commit.trim().is_empty() {
2776	        return Ok(false);
2777	    }
2778	    let verified = Command::new("git")
2779	        .current_dir(root)
2780	        .args(["-c", "gpg.format=ssh", "-c"])
2781	        .arg(format!("gpg.ssh.allowedSignersFile={signers}"))
2782	        .args(["verify-commit", commit.trim()])
2783	        .output()
2784	        .context("git verify-commit")?;
2785	    Ok(verified.status.success())
2786	}
