2788	/// The findings a record leaves unresolved after standing rulings: verified,
2789	/// independently reproduced, not resolved by a fix proof, and not covered by
2790	/// a ruling in force on the same attack class and target file. Read as plain
2791	/// JSON so the count is over what was persisted.
2792	pub fn effective_unresolved_findings_repo(root: &Utf8Path, record: &Utf8Path) -> Result<u64> {
2793	    let value: serde_json::Value =
2794	        serde_json::from_slice(&fs::read(record)?).with_context(|| format!("parse {record}"))?;
2795	    let in_force = rulings(root)?
2796	        .into_iter()
2797	        .filter(|ruling| ruling_in_force(root, ruling).unwrap_or(false))
2798	        .collect::<Vec<_>>();
2799	    effective_unresolved_findings(&in_force, &value, record)
2800	}
