2802	/// The count, given the rulings already established to be in force. Split from
2803	/// the repository walk so the clearance rules can be exercised without a
2804	/// signing key: a rule the tests cannot reach is a rule nothing checks.
2805	fn effective_unresolved_findings(
2806	    in_force: &[Ruling],
2807	    value: &serde_json::Value,
2808	    record: &Utf8Path,
2809	) -> Result<u64> {
2810	    // Counted from each attempt's own flags, not through the findings list:
2811	    // a verified, reproduced attempt the reviewer forgot to list as a finding
2812	    // is still unresolved.
2813	    let mut unresolved = 0u64;
2814	    let mut cleared: BTreeMap<String, u64> = BTreeMap::new();
2815	    for attempt in value["attempts"].as_array().into_iter().flatten() {
2816	        let class = attempt["attack_class"].as_str().unwrap_or_default();
2817	        let target = attempt["target"].as_str().unwrap_or_default();
2818	        if attempt["classification"].as_str() != Some("verified_defect")
2819	            || !attempt["independently_reproduced"]
2820	                .as_bool()
2821	                .unwrap_or(false)
2822	            || attempt["resolved"].as_bool().unwrap_or(false)
2823	        {
2824	            continue;
2825	        }
2826	        let target_file = target.split(':').next().unwrap_or(target);
2827	        let prose = format!(
2828	            "{} {}",
2829	            attempt["attempt"].as_str().unwrap_or_default(),
2830	            attempt["observed_result"].as_str().unwrap_or_default()
2831	        )
2832	        .to_ascii_lowercase();
2833	        // Blind pass 1 at c29bc0ea (A08): a ruling matched on class, file and
2834	        // prose substrings, so an unrelated defect in the same file whose
2835	        // wording happened to carry the required phrases was cleared in
2836	        // silence. Two things changed. A ruling that names a coordinate is
2837	        // held to it, not merely to the file. And a ruling clears at most one
2838	        // attempt per record: matching a second is evidence the phrases are
2839	        // too broad, and the answer to that is a refusal, not two clearances.
2840	        let matched = in_force
2841	            .iter()
2842	            .filter(|ruling| {
2843	                ruling.attack_class == class
2844	                    && if ruling.target.contains(':') {
2845	                        ruling.target == target
2846	                    } else {
2847	                        ruling.target == target_file
2848	                    }
2849	                    && ruling
2850	                        .claim_requires
2851	                        .iter()
2852	                        .all(|phrase| prose.contains(phrase.as_str()))
2853	                    && !ruling
2854	                        .claim_excludes
2855	                        .iter()
2856	                        .any(|phrase| prose.contains(phrase.as_str()))
2857	            })
2858	            .collect::<Vec<_>>();
2859	        for ruling in &matched {
2860	            *cleared.entry(ruling.id.clone()).or_insert(0u64) += 1;
2861	        }
2862	        if matched.is_empty() {
2863	            unresolved += 1;
2864	        }
2865	    }
2866	    for (id, count) in &cleared {
2867	        anyhow::ensure!(
2868	            *count <= 1,
2869	            "ruling {id} cleared {count} separate findings in {record}; a ruling \
2870	                 answers one claim, so phrases matching more than one are too \
2871	                 broad to stand"
2872	        );
2873	    }
2874	    Ok(unresolved)
2875	}
