   688	fn verify_markdown_review_blocks(root: &Utf8Path, packet: &Packet) -> Result<()> {
   689	    let text = fs::read_to_string(root.join("docs/execution/phase1-suite-review.md"))
   690	        .context("read the review markdown")?;
   691	    let fields = [
   692	        "reviewer identity hash",
   693	        "reviewer kind/model family",
   694	        "isolated session hash",
   695	        "sanitized prompt hash",
   696	        "fixed-base hash",
   697	        "blindness proof",
   698	        "concrete falsification attempts (minimum 12)",
   699	        "attempted caught violations",
   700	        "findings artifact hash",
   701	        "unresolved verified findings",
   702	        "result",
   703	    ];
   704	    let cell = |value: &str| value.replace('|', "\\|").replace('\n', " ");
   705	    for (index, review) in packet.reviews.iter().enumerate() {
   706	        let marker = format!("### Pass {}", index + 1);
   707	        let block_at = text
   708	            .find(&marker)
   709	            .with_context(|| format!("review markdown has no {marker:?} block"))?;
   710	        let block = &text[block_at..];
   711	        let block = &block[..block[1..].find("\n### ").map_or(block.len(), |i| i + 1)];
   712	        let row_value = |field: &str| -> Result<String> {
   713	            let prefix = format!("| {field} | ");
   714	            let line = block
   715	                .lines()
   716	                .find(|line| line.starts_with(&prefix))
   717	                .with_context(|| format!("{marker}: no row for {field:?}"))?;
   718	            Ok(line[prefix.len()..]
   719	                .trim_end()
   720	                .trim_end_matches('|')
   721	                .trim()
