  3588	    fixed_base: &ReviewFixedBase,
  3589	    who: &str,
  3590	    attempt: &ReviewRecordAttempt,
  3591	) -> Result<()> {
  3592	    if !attempt.resolved {
  3593	        return Ok(());
  3594	    }
