  3596	        format!(
  3597	            "{who}: resolved finding attempt {:?} has no resolution proof",
  3598	            attempt.id
  3599	        )
  3600	    })?;
  3601	    require_git_object_id(&format!("{who} resolution commit"), &resolution.commit)?;
  3602	    let fixed_oid = git_text(root, &["rev-parse", &fixed_base.commit])?;
  3603	    let resolution_oid = git_text(root, &["rev-parse", &resolution.commit])?;
  3604	    anyhow::ensure!(
  3605	        fixed_oid != resolution_oid,
  3606	        "{who}: resolution commit must be a strict descendant of fixed base"
  3607	    );
  3608	    git_is_ancestor(root, &fixed_base.commit, &resolution.commit).with_context(|| {
  3609	        format!(
  3610	            "{who}: resolution commit {} is not a descendant of fixed base {}",
  3611	            resolution.commit, fixed_base.commit
  3612	        )
  3613	    })?;
  3614	    git_is_ancestor(root, &resolution.commit, "HEAD").with_context(|| {
  3615	        format!(
  3616	            "{who}: resolution commit {} is not reachable from current qualification HEAD",
  3617	            resolution.commit
  3618	        )
  3619	    })?;
  3620	    let evidence_path = safe_repo_path(root, &resolution.evidence_path, who)?;
  3621	    let evidence_bytes = fs::read(&evidence_path)
  3622	        .with_context(|| format!("{evidence_path}: resolution evidence is missing"))?;
  3623	    let evidence_text = String::from_utf8_lossy(&evidence_bytes);
  3624	    anyhow::ensure!(
  3625	        evidence_text.contains(&attempt.id)
  3626	            && evidence_text.contains(&attempt.target)
  3627	            && evidence_text.contains(&resolution.coordinate),
  3628	        "{who}: resolution evidence must name attempted finding {}, target {}, and fix coordinate {}",
  3629	        attempt.id,
