13454	        category,
13455	        "empty"
13456	            | "duplicate-id"
13457	            | "missing-node"
13458	            | "cycle"
13459	            | "unknown-kind"
13460	            | "external-value"
13461	            | "comment"
13462	            | "truncated-json"
13463	            | "invalid-json"
13464	            | "hostile"
13465	    );
