13516	/// The node and relation counts a category promises.
13517	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
13518	struct InterchangeShape {
13519	    nodes: usize,
13520	    relations: usize,
13521	    payload_bytes_at_least: usize,
13522	}
