13524	/// A transaction with the shape its category names: `single-edge` is two nodes
13525	/// and one relation, `dag` a diamond, `wide` a root with eight children, `deep`
13526	/// a chain of twelve, `large-payload` one node carrying 64 KiB of text.
13527	fn interchange_transaction(
13528	    category: &str,
13529	    rng: &mut Rng,
13530	    text: &str,
13531	    durable: bool,
13532	) -> (liminal_graph::Transaction, InterchangeShape) {
13533	    use liminal_graph::{
13534	        Node, NodeFlags, Operation, Origin, PayloadRef, Relation, RelationFlags, Target,
13535	        Transaction, TxnMeta,
13536	    };
13537	    let node = |rng: &mut Rng, payload: PayloadRef, durable: bool| Node {
13538	        id: liminal_id::NodeId::from_uuid(rng.uuid()),
13539	        kind: liminal_graph::KindId(u32::try_from(rng.below(8)).expect("kind fits")),
13540	        payload,
13541	        revision: liminal_id::RevisionId(rng.below(1_000)),
13542	        flags: if durable {
13543	            NodeFlags::HAS_DURABLE_ID
13544	        } else {
13545	            NodeFlags::default()
13546	        },
13547	    };
13548	    let relation =
13549	        |rng: &mut Rng, source: liminal_id::NodeId, target: liminal_id::NodeId| Relation {
13550	            id: liminal_id::RelationId::from_uuid(rng.uuid()),
13551	            source,
13552	            target: Target::Node(target),
13553	            kind: liminal_graph::KindId(u32::try_from(rng.below(8)).expect("kind fits")),
13554	            payload: PayloadRef::None,
13555	            revision: liminal_id::RevisionId(0),
13556	            flags: RelationFlags(0),
13557	            requires: None,
13558	        };
13559	    let (nodes, edges, payload_floor): (Vec<Node>, Vec<(usize, usize)>, usize) = match category {
13560	        "single-edge" => (
13561	            vec![
13562	                node(rng, PayloadRef::Text(text.to_owned()), durable),
13563	                node(rng, PayloadRef::None, false),
13564	            ],
13565	            vec![(0, 1)],
13566	            0,
13567	        ),
13568	        "dag" => (
13569	            (0..4).map(|_| node(rng, PayloadRef::None, false)).collect(),
13570	            vec![(0, 1), (0, 2), (1, 3), (2, 3)],
13571	            0,
13572	        ),
13573	        "wide" => (
13574	            (0..9).map(|_| node(rng, PayloadRef::None, false)).collect(),
13575	            (1..9).map(|child| (0, child)).collect(),
13576	            0,
13577	        ),
13578	        "deep" => (
13579	            (0..12)
13580	                .map(|_| node(rng, PayloadRef::None, false))
13581	                .collect(),
13582	            (0..11).map(|index| (index, index + 1)).collect(),
13583	            0,
13584	        ),
13585	        "large-payload" => (
13586	            vec![node(
13587	                rng,
13588	                PayloadRef::Text(text.repeat(65_536 / text.len().max(1) + 1)),
13589	                durable,
13590	            )],
13591	            Vec::new(),
13592	            65_536,
13593	        ),
13594	        // `single-node` and every category the seed table lists without a
13595	        // dedicated shape.
13596	        _ => {
13597	            let payload = if rng.below(4) == 0 {
13598	                PayloadRef::None
13599	            } else {
13600	                PayloadRef::Text(text.to_owned())
13601	            };
13602	            (vec![node(rng, payload, durable)], Vec::new(), 0)
13603	        }
13604	    };
13605	    let shape = InterchangeShape {
13606	        nodes: nodes.len(),
13607	        relations: edges.len(),
13608	        payload_bytes_at_least: payload_floor,
13609	    };
13610	    let ids = nodes.iter().map(|n| n.id).collect::<Vec<_>>();
13611	    let mut ops = nodes
13612	        .into_iter()
13613	        .map(|node| Operation::CreateNode { node })
13614	        .collect::<Vec<_>>();
13615	    for (from, to) in edges {
13616	        ops.push(Operation::AddRelation {
13617	            relation: relation(rng, ids[from], ids[to]),
13618	        });
13619	    }
13620	    let txn = Transaction {
13621	        id: liminal_id::TransactionId::from_uuid(rng.uuid()),
13622	        parent: liminal_id::GraphRevisionId(rng.below(1_000)),
13623	        meta: TxnMeta {
13624	            actor: None,
13625	            origin: Origin::Human,
13626	            at: liminal_id::Timestamp(i64::try_from(rng.below(1_000_000)).expect("fits")),
13627	            provenance: None,
13628	            inverse: None,
13629	        },
13630	        ops,
13631	    };
13632	    (txn, shape)
13633	}
