13635	/// Independent oracle for the interchange codec: structural round-trip,
13636	/// byte-stable re-encoding, and the promised shape counted in the encoded JSON
13637	/// by a parser that is not the codec (serde_json::Value), so a codec that
13638	/// silently dropped an operation could not certify itself.
13639	fn independent_oracle_interchange(
13640	    txn: &liminal_graph::Transaction,
13641	    decoded: &liminal_graph::Transaction,
13642	    once: &[u8],
13643	    twice: &[u8],
13644	    shape: InterchangeShape,
13645	) -> Result<Vec<u8>> {
13646	    anyhow::ensure!(
13647	        txn == decoded,
13648	        "interchange round trip changed the transaction"
13649	    );
13650	    anyhow::ensure!(once == twice, "interchange encoding is not byte-stable");
13651	    let value: serde_json::Value = serde_json::from_slice(once)?;
13652	    let ops = value["ops"]
13653	        .as_array()
13654	        .context("encoded transaction has no ops array")?;
13655	    let count = |key: &str| ops.iter().filter(|op| op.get(key).is_some()).count();
13656	    anyhow::ensure!(
13657	        count("create-node") == shape.nodes && count("add-relation") == shape.relations,
13658	        "encoded shape differs from the category's promise: {shape:?}"
13659	    );
13660	    // Blind pass 1 at f360e90 (A02): a renamed field round-trips through the
13661	    // same serde on both sides. The published schema is a closed key set.
13662	    // Sorted on this side: the pin is "no field added, removed or renamed",
13663	    // not the encoder's key order.
13664	    let keys = |value: &serde_json::Value| -> Vec<String> {
13665	        let mut keys: Vec<String> = value
13666	            .as_object()
13667	            .map(|map| map.keys().cloned().collect())
13668	            .unwrap_or_default();
13669	        keys.sort_unstable();
13670	        keys
13671	    };
13672	    anyhow::ensure!(
13673	        keys(&value) == ["id", "meta", "ops", "parent"],
13674	        "encoded transaction keys are not the published schema: {:?}",
13675	        keys(&value)
13676	    );
13677	    for op in ops {
13678	        if let Some(node) = op.pointer("/create-node/node") {
13679	            anyhow::ensure!(
13680	                keys(node) == ["flags", "id", "kind", "payload", "revision"],
13681	                "encoded node keys are not the published schema: {:?}",
13682	                keys(node)
13683	            );
13684	        }
13685	        if let Some(relation) = op.pointer("/add-relation/relation") {
13686	            anyhow::ensure!(
13687	                keys(relation)
13688	                    == [
13689	                        "flags", "id", "kind", "payload", "requires", "revision", "source",
13690	                        "target"
13691	                    ],
13692	                "encoded relation keys are not the published schema: {:?}",
13693	                keys(relation)
13694	            );
13695	        }
13696	    }
13697	    let payload_bytes = ops
13698	        .iter()
13699	        .filter_map(|op| op.pointer("/create-node/node/payload/text"))
13700	        .filter_map(serde_json::Value::as_str)
13701	        .map(str::len)
13702	        .max()
13703	        .unwrap_or(0);
13704	    anyhow::ensure!(
13705	        payload_bytes >= shape.payload_bytes_at_least,
13706	        "encoded payload {payload_bytes} bytes is under the category's floor"
13707	    );
13708	    Ok(once.to_vec())
13709	}
