13723	    match category {
13724	        "empty" => String::new(),
13725	        "invalid-span" => format!("{word} {{#open\n\n{word} {{# spaced }}"),
13726	        "truncated" => format!("{word} {{#full}}\n\n{word} {{#cu"),
13727	        "hostile" => format!(
13728	            "{word}\0 {{#\u{202e}}} {{#{{#nested}}}} {{#{}}}",
13729	            "x".repeat(4096)
13730	        ),
13731	        other => format!("{other}:{word}"),
13732	    }
13733	}
