13735	fn case_transform(rng: &mut Rng) -> Result<Case> {
13736	    use liminal_source::merge::three_way;
13737	
13738	    let category = rng.category("transforms/projections");
13739	    if matches!(category, "empty" | "invalid-span" | "truncated" | "hostile") {
13740	        // Negative inputs still cross the production merge implementation.
13741	        // Blind pass 1 at 612cbcc (A03): every category used to become an
13742	        // ordinary label string, so the "negative" tested only the generator's
13743	        // branch. Each category now constructs the shape it names.
13744	        let malformed = transform_negative_input(category, rng);
13745	        let outcome = three_way("{#negative}", &malformed, "{#negative}");
13746	        // Totality is the property: the merge returned rather than panicked.
13747	        // A disjoint outcome must carry the malformed side verbatim; any other
13748	        // outcome class is the transform refusing the shape, recorded as such.
13749	        if let liminal_source::merge::MergeOutcome::Disjoint { merged } = &outcome {
13750	            // The merge normalizes layout (base slot order, block spacing), so
13751	            // verbatim containment is not the property; every token of the
13752	            // malformed side surviving is.
13753	            let mut missing = malformed.split_whitespace().collect::<Vec<_>>();
13754	            for token in merged.split_whitespace() {
13755	                if let Some(index) = missing.iter().position(|m| *m == token) {
13756	                    missing.swap_remove(index);
13757	                }
13758	            }
13759	            anyhow::ensure!(
13760	                missing.is_empty(),
13761	                "transform negative category {category} lost malformed input tokens {missing:?}"
13762	            );
13763	        }
13764	        let witness = format!("transform-negative:{category}:{outcome:?}").into_bytes();
13765	        return Ok(Case::Negative { category, witness });
13766	    }
13767	    let blocks = match category {
13768	        "deep" => 12,
13769	        "wide" | "large-patch" => 8,
13770	        _ => 1 + rng.below(4),
13771	    };
13772	    let base = (0..blocks)
13773	        .map(|i| format!("{} {{#b{i}}}", rng.word()))
13774	        .collect::<Vec<_>>()
13775	        .join("\n\n");
