13777	    if base.trim().is_empty() {
13778	        return Ok(Case::Negative {
13779	            category,
13780	            witness: format!("degenerate-base:{base:?}").into_bytes(),
13781	        });
13782	    }
13783	    let token = rng.word();
13784	    let mut lines = base.lines().map(str::to_owned).collect::<Vec<_>>();
