13788	        "identity" | "deep" | "wide" | "large-patch" => (base.clone(), base.clone()),
13789	        "insert" => (format!("{token}\n\n{base}"), base.clone()),
13790	        "delete" => (
13791	            lines.iter().skip(1).cloned().collect::<Vec<_>>().join("\n"),
13792	            base.clone(),
13793	        ),
13794	        "replace" => (
13795	            base.replacen(&first, &format!("{token} {first}"), 1),
13796	            base.clone(),
13797	        ),
13798	        "move" => {
13799	            lines.reverse();
13800	            (lines.join("\n"), base.clone())
13801	        }
13802	        "overlap" => (
13803	            base.replacen(&first, &format!("ours {first}"), 1),
13804	            base.replacen(&first, &format!("theirs {first}"), 1),
13805	        ),
13806	        "commute" => (
13807	            base.replacen(&first, &format!("ours {first}"), 1),
13808	            base.replacen(&second, &format!("theirs {second}"), 1),
13809	        ),
13810	        "conflict" => (
13811	            base.replacen(&first, &format!("left {first}"), 1),
13812	            base.replacen(&first, &format!("right {first}"), 1),
13813	        ),
13814	        "boundary-span" => (format!("\n{base}\n"), base.clone()),
