14137	            "truncated" => b"{".to_vec(),
14138	            "hostile" => vec![0xff, 0x00, 0x7f],
14139	            "invalid-token" => br#"{"perspective":"unknown"}"#.to_vec(),
14140	            "unknown-perspective" => br#"{"perspective":{"future":true}}"#.to_vec(),
