14237	/// Reject a case count that is zero or beyond the safety limit.
14238	fn validate_case_count(cases: u64) -> Result<()> {
14239	    if cases == 0 {
14240	        anyhow::bail!("generated case count must be positive");
14241	    }
14242	    if cases > 10_000_000 {
14243	        anyhow::bail!("generated case count exceeds safety limit: {cases} > 10000000");
14244	    }
14245	    Ok(())
14246	}
