14262	    let mut evidence = Vec::new();
14263	    let mut timings = Vec::new();
14264	    for (index, (family, run)) in families.into_iter().enumerate() {
14265	        let seed = 0x9E37_79B9_7F4A_7C15_u64 ^ (index as u64).wrapping_mul(0x0100_0000_01B3);
14266	        let mut rng = Rng(seed);
14267	        let started = Instant::now();
14268	        let mut digest = blake3::Hasher::new();
14269	        digest.update(&seed.to_le_bytes());
