14288	                Case::Accepted { category, witness } => {
14289	                    // A family that witnesses nothing would restore exactly the
14290	                    // #16 defect: a digest independent of the code under test.
14291	                    anyhow::ensure!(
14292	                        !witness.is_empty(),
14293	                        "{family}: accepted attempt {attempts} with an empty witness, so \
14294	                         the evidence hash would not depend on what the code produced"
14295	                    );
14296	                    accepted += 1;
14297	                    *category_counts.entry(category.to_owned()).or_default() += 1;
14298	                    digest.update(b"A");
14299	                    digest.update(category.as_bytes());
14300	                    digest.update(&witness);
14301	                }
14302	                Case::Discarded { category, witness } => {
14303	                    anyhow::ensure!(
14304	                        !witness.is_empty(),
14305	                        "{family}: discarded attempt {attempts} with an empty witness, so \
14306	                         the evidence records that something was discarded and not what"
14307	                    );
14308	                    discards += 1;
14309	                    *category_counts.entry(category.to_owned()).or_default() += 1;
14310	                    digest.update(b"D");
14311	                    digest.update(category.as_bytes());
14312	                    digest.update(&witness);
14313	                }
14314	                Case::Negative { category, witness } => {
14315	                    anyhow::ensure!(
