  199	/// The crate's own sources, concatenated, for the crate owning `file`. Blind
  200	/// pass 1 at c29bc0ea (A02): the closure followed same-file functions only, so
  201	/// a helper one module away carried the oracle to the production path it
  202	/// judges and named nothing.
  203	fn crate_sources(root: &Utf8Path, file: &str) -> Result<String> {
  204	    let path = root.join(file);
  205	    let Some(src) = path.parent() else {
  206	        return fs::read_to_string(&path).with_context(|| format!("read {path}"));
  207	    };
  208	    let mut stack = vec![src.to_owned()];
  209	    let mut files = Vec::new();
  210	    while let Some(dir) = stack.pop() {
  211	        let mut entries = fs::read_dir(dir.as_std_path())
  212	            .with_context(|| format!("read {dir}"))?
  213	            .map(|entry| entry.map(|e| e.path()))
  214	            .collect::<std::io::Result<Vec<_>>>()?;
  215	        entries.sort();
  216	        for entry in entries {
  217	            let entry = Utf8PathBuf::from_path_buf(entry)
  218	                .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
  219	            if entry.is_dir() {
  220	                stack.push(entry);
  221	            } else if entry.extension() == Some("rs") {
  222	                files.push(entry);
  223	            }
  224	        }
  225	    }
  226	    files.sort();
  227	    let mut combined = String::new();
  228	    for file in files {
  229	        combined.push_str(&fs::read_to_string(&file).with_context(|| format!("read {file}"))?);
  230	        combined.push('\n');
  231	    }
  232	    Ok(combined)
  233	}
