  235	/// Every function in `text` reachable from `name`, concatenated. A helper the
  236	/// oracle calls is part of the oracle for ADR-0020 §5: independence that one
  237	/// hop defeats is not independence.
  238	fn oracle_reachable_body(text: &str, name: &str) -> String {
  239	    let defined = text
  240	        .lines()
  241	        .filter_map(|line| {
  242	            let trimmed = line.trim_start();
  243	            // Review of f4d42d3: `pub(crate) fn helper` named no prefix, so a
  244	            // helper declared that way was missing from the closure and the
  245	            // oracle could reach production through it. Review of 4bc26b6d:
  246	            // the first fix tested `pub(...)` as a whole-prefix alternative,
  247	            // which `pub(crate) async fn` fails on both arms. Review of
  248	            // `39de4daa`: a per-word check still missed `pub(in crate::x) fn`,
  249	            // which splits into two words. The restriction is removed as a
  250	            // span, then the remaining qualifiers are checked word by word.
  251	            // `unsafe` is among them because adding a helper to the closure
  252	            // can only add refusals; dropping one is the direction that lets
  253	            // an oracle reach production unnoticed.
  254	            if let Some(rest) = trimmed.strip_prefix("macro_rules! ") {
  255	                let end = rest.find(['{', '(', '[']).unwrap_or(rest.len());
  256	                return Some(rest[..end].trim().to_owned());
  257	            }
  258	            let rest = trimmed
  259	                .split_once("fn ")
  260	                .filter(|(before, _)| {
  261	                    let mut qualifiers = (*before).to_owned();
  262	                    while let Some(start) = qualifiers.find("pub(") {
  263	                        let Some(offset) = qualifiers[start..].find(')') else {
  264	                            break;
  265	                        };
  266	                        qualifiers.replace_range(start..=start + offset, "");
  267	                    }
  268	                    qualifiers
  269	                        .split_whitespace()
  270	                        .all(|word| matches!(word, "pub" | "async" | "const" | "unsafe"))
  271	                })
  272	                .map(|(_, rest)| rest)?;
  273	            let end = rest.find(['(', '<'])?;
  274	            Some(rest[..end].to_owned())
  275	        })
  276	        .collect::<BTreeSet<_>>();
  277	    let mut seen = BTreeSet::new();
  278	    let mut queue = vec![name.to_owned()];
  279	    let mut combined = String::new();
  280	    while let Some(current) = queue.pop() {
  281	        if !seen.insert(current.clone()) {
  282	            continue;
  283	        }
  284	        for body in item_bodies(text, &current) {
  285	            combined.push_str(body);
  286	            combined.push('\n');
  287	            for callee in &defined {
  288	                // Blind pass 1 at `6b36bbb9` (A01): only the CALL form was
  289	                // followed, so `let h = helper; h(input)` carried the oracle
  290	                // to a body the closure never entered — the same value
  291	                // indirection that defeated the alias scan one lane earlier.
  292	                // Naming a function at all pulls its body in.
  293	                if !seen.contains(callee) && mentions_word(body, callee) {
  294	                    queue.push(callee.clone());
  295	                }
  296	            }
  297	        }
  298	    }
  299	    combined
  300	}
