 1742	/// Characters the dialect lowers into structure: lists, headings, quotes,
 1743	/// tables and fences. Losing one of these to formatting is the formatter
 1744	/// working; losing anything else that is not whitespace is losing content.
 1745	const STRUCTURAL_MARKUP: [char; 7] = ['-', '*', '#', '>', '|', '+', '`'];
 1746	
 1747	/// A document's words in order. An escape stands for the character it
 1748	/// denotes, so `\n` inside an emitted literal is a separator and not the
 1749	/// letter `n` glued to the next word — without that, escaping a newline
 1750	/// looks like reordering.
 1751	///
 1752	/// Review of `ec045588`: an escape the emitter does not produce — `\u` with
 1753	/// too few hex digits, say — is normalised imperfectly, and that is safe
 1754	/// because this runs over BOTH sides. Mangling can only add words to the
 1755	/// output, never remove one from the source, and added words are what a
 1756	/// subsequence tolerates. Every character the emitter actually escapes is
 1757	/// non-alphanumeric, so it already separates words in the source.
 1758	fn sequence(text: &str) -> Vec<String> {
 1759	    let mut plain = String::with_capacity(text.len());
 1760	    let mut chars = text.chars().peekable();
 1761	    while let Some(ch) = chars.next() {
 1762	        if ch != '\\' {
 1763	            plain.push(ch);
 1764	            continue;
 1765	        }
 1766	        // `\uXXXX` and `\xNN` denote one character each; anything else
 1767	        // after a backslash denotes the character that follows it.
 1768	        let digits = match chars.peek() {
 1769	            Some('u') => 4,
 1770	            Some('x') => 2,
 1771	            _ => 0,
 1772	        };
 1773	        chars.next();
 1774	        for _ in 0..digits {
 1775	            if chars.peek().is_some_and(char::is_ascii_hexdigit) {
 1776	                chars.next();
 1777	            }
 1778	        }
 1779	        plain.push(' ');
 1780	    }
 1781	    plain
 1782	        .split(|ch: char| !ch.is_alphanumeric())
 1783	        .filter(|run| !run.is_empty())
 1784	        .map(str::to_owned)
 1785	        .collect()
 1786	}
