13320	/// Family 0 — source/CST/formatting. Metamorphic relations: **lossless
13321	/// emit** (the CST must reproduce its input byte-for-byte) and **format
13322	/// idempotence**, both compared over bytes rather than parsed values.
13323	fn case_source_cst(rng: &mut Rng) -> Result<Case> {
13324	    // Blind pass 1 at aa00d41 (A01): a formatter error became a Negative case
13325	    // whatever the category, so a formatter that lost support for nested or
13326	    // deep documents reclassified them as negatives and the run still reached
13327	    // its accepted target from the categories that still worked. Only the
13328	    // categories that DECLARE malformed input may be refused.
13329	    const REFUSABLE: [&str; 5] = [
13330	        "truncated",
13331	        "unterminated",
13332	        "control-byte",
13333	        "invalid-utf8",
13334	        "hostile",
13335	    ];
13336	    let category = rng.category("source/CST/formatting");
13337	    let token = rng.word();
13338	    let bytes = match category {
13339	        "empty" => Vec::new(),
13340	        "single-token" => token.as_bytes().to_vec(),
13341	        "whitespace" => b" \t\n".to_vec(),
13342	        "unicode" => format!("{token} βeta").into_bytes(),
13343	        "long-line" => format!("{}-{token}", token.repeat(64)).into_bytes(),
13344	        "truncated" => format!("{token} {{#").into_bytes(),
13345	        "unterminated" => format!("{token} {{#{token}").into_bytes(),
13346	        "nested" => format!("{token} {{#outer {{#{token}}}}}").into_bytes(),
13347	        "deep" => format!("{} {token}", "{#".repeat(24)).into_bytes(),
13348	        // Blind pass 1 at `2bba9071` (A01): `boundary-offset` renders two
13349	        // blocks with IDENTICAL text, which a constant hash satisfies — it
13350	        // passes the equal-text arm and never meets the other. This renders
13351	        // two blocks of DIFFERENT width, so a hash that ignores its bytes
13352	        // collides across them and the relation has both arms to check. A
13353	        // durable marker cannot be used for this: the formatter lifts `{#id}`
13354	        // into an attribute, which moves a word and reads as reordering.
13355	        "wide" => {
13356	            let row = |count: usize| {
13357	                (0..count)
13358	                    .map(|_| token.clone())
13359	                    .collect::<Vec<_>>()
13360	                    .join(" ")
13361	            };
13362	            format!("{}\n\n{}", row(32), row(16)).into_bytes()
13363	        }
13364	        "control-byte" => format!("{token}\x01{token}").into_bytes(),
13365	        "invalid-utf8" => vec![0xff, 0xfe],
13366	        "comment" => format!("{token} <!-- {token} -->").into_bytes(),
13367	        "escape" => format!(r"{token} \ {token}").into_bytes(),
13368	        // Blind pass 1 at `ec045588` (A01): every generated source held at
13369	        // most ONE coarse block, so the per-document hash relation F-60 added
13370	        // — equal text hashes alike, different text does not — had nothing to
13371	        // relate and a constant hash passed 100,000 cases. A blank line makes
13372	        // two blocks, and repeating the token makes them equal, which is the
13373	        // arm a constant hash satisfies and a text-blind one does not.
13374	        "boundary-offset" => format!("{token}\n\n{token}").into_bytes(),
13375	        "hostile" => format!("{token}\0\x7f").into_bytes(),
13376	        other => unreachable!("unknown source category {other}"),
13377	    };
13378	    let Ok(source) = String::from_utf8(bytes.clone()) else {
13379	        let basis = liminal_source::SourceBasis {
13380	            source: liminal_id::SourceId::from_name("haqp-generated"),
13381	            content_hash: liminal_id::ContentHash::of(&bytes),
13382	        };
13383	        anyhow::ensure!(
13384	            liminal_source::Utf8HolderView::from_bytes(basis, &bytes).is_err(),
13385	            "invalid-utf8 source unexpectedly entered Utf8HolderView"
13386	        );
13387	        return Ok(Case::Negative {
13388	            category,
13389	            witness: bytes,
13390	        });
13391	    };
13392	    // Out of domain: the compact surface has no all-whitespace document.
13393	    if source.trim().is_empty() {
13394	        return Ok(Case::Negative {
13395	            category,
13396	            witness: format!("whitespace-source:{source:?}").into_bytes(),
13397	        });
13398	    }
13399	    let basis = liminal_source::SourceBasis {
13400	        source: liminal_id::SourceId::from_name("haqp-generated"),
13401	        content_hash: liminal_id::ContentHash::of(source.as_bytes()),
13402	    };
13403	    let Ok(view) = liminal_source::Utf8HolderView::from_bytes(basis, source.as_bytes()) else {
13404	        return Ok(Case::Negative {
13405	            category,
13406	            witness: source.into_bytes(),
13407	        });
13408	    };
13409	    let cst = liminal_cst::parse(&view);
13410	    let emitted = cst.emit_lossless();
13411	    // Blind pass 1 at 9eca4f0 (A01): the campaign exercised `parse` only, so
13412	    // `coarse_parse` — the other public entry point, the one that must never
13413	    // reject — could return empty block metadata for every input and no
13414	    // generated case would notice.
13415	    let coarse = liminal_cst::coarse_parse(&source);
13416	    let fmt = liminal_format::MarkdownFormatter::default();
13417	    let Ok(once) = fmt.format(&source) else {
13418	        anyhow::ensure!(
13419	            REFUSABLE.contains(&category),
13420	            "the formatter refused valid-domain category {category}: a refusal there is lost \
13421	             support, not a negative case (source {source:?})"
13422	        );
13423	        return Ok(Case::Negative {
13424	            category,
13425	            witness: source.into_bytes(),
13426	        });
13427	    };
13428	    let Ok(twice) = fmt.format(&once) else {
13429	        anyhow::ensure!(
13430	            REFUSABLE.contains(&category),
13431	            "the formatter refused its own output for valid-domain category {category}: \
13432	             formatting is not total there (source {source:?})"
13433	        );
13434	        return Ok(Case::Negative {
13435	            category,
13436	            witness: once.into_bytes(),
13437	        });
13438	    };
13439	    let witness = independent_oracle_source_cst(&source, &emitted, &once, &twice, &token, &coarse)?;
13440	    Ok(Case::Accepted { category, witness })
13441	}
