13443	/// Family 1 — graph/interchange codecs.
13444	///
13445	/// Metamorphic relation: **byte-canonical stability**. Re-serializing a value
13446	/// decoded from canonical bytes must reproduce those bytes exactly. The
13447	/// comparison is over BYTES, never the type's own `PartialEq`, so a broken
13448	/// `Eq` cannot make this pass (ADR-0020 §5).
13449	fn case_interchange(rng: &mut Rng) -> Result<Case> {
13450	    use liminal_graph::Node;
13451	
13452	    let category = rng.category("graph/interchange codecs");
13453	    let malformed = matches!(
13454	        category,
13455	        "empty"
13456	            | "duplicate-id"
13457	            | "missing-node"
13458	            | "cycle"
13459	            | "unknown-kind"
13460	            | "external-value"
13461	            | "comment"
13462	            | "truncated-json"
13463	            | "invalid-json"
13464	            | "hostile"
13465	    );
13466	    if malformed {
13467	        let raw = match category {
13468	            "empty" => Vec::new(),
13469	            "duplicate-id" => br#"{"id":"00000000-0000-0000-0000-000000000001","id":"00000000-0000-0000-0000-000000000002","kind":1,"payload":"none","revision":0,"flags":0}"#.to_vec(),
13470	            "missing-node" => br"{}".to_vec(),
13471	            "cycle" => br#"{"id":"00000000-0000-0000-0000-000000000001","kind":1,"payload":{"cycle":["a","b","a"]},"revision":0,"flags":0}"#.to_vec(),
13472	            "unknown-kind" => br#"{"id":"00000000-0000-0000-0000-000000000001","kind":"unknown","payload":"none","revision":0,"flags":0}"#.to_vec(),
13473	            "external-value" => br#"{"id":"00000000-0000-0000-0000-000000000001","kind":1,"payload":{"external-value":"source"},"revision":0,"flags":0}"#.to_vec(),
13474	            "comment" => br#"{"id":"00000000-0000-0000-0000-000000000001","kind":1,"payload":{"comment":"note"},"revision":0,"flags":0}"#.to_vec(),
13475	            "truncated-json" => format!(r#"{{"category":"{category}""#).into_bytes(),
13476	            "invalid-json" => {
13477	                let mut bytes = format!("{category}\0").into_bytes();
13478	                bytes.push(0xff);
13479	                bytes
13480	            }
13481	            "hostile" => vec![0, 0xff, 0x7f],
13482	            _ => unreachable!("unknown graph negative category {category}"),
13483	        };
13484	        anyhow::ensure!(
13485	            serde_json::from_slice::<Node>(&raw).is_err(),
13486	            "graph negative category {category} unexpectedly decoded"
13487	        );
13488	        let witness = if raw.is_empty() {
13489	            format!("{category}:empty").into_bytes()
13490	        } else {
13491	            raw
13492	        };
13493	        return Ok(Case::Negative { category, witness });
13494	    }
13495	    // Blind pass 1 at 612cbcc (A07): every accepted category built one Node
13496	    // with the category's name leaked into its payload, and a Node is not even
13497	    // the codec's unit — the fuzz target decodes a Transaction. Each category
13498	    // now builds the transaction shape it names, and the oracle counts that
13499	    // shape in the encoded JSON independently of the codec's own equality.
13500	    let text = format!("{category}:{}", rng.word());
13501	    let durable = rng.below(2) == 1;
13502	    if matches!(category, "single-node") && durable && text.trim().is_empty() {
13503	        return Ok(Case::Discarded {
13504	            category,
13505	            witness: format!("durable-without-payload:{text:?}").into_bytes(),
13506	        });
13507	    }
13508	    let (txn, shape) = interchange_transaction(category, rng, &text, durable);
13509	    let once = serde_json::to_vec(&txn)?;
13510	    let decoded: liminal_graph::Transaction = serde_json::from_slice(&once)?;
13511	    let twice = serde_json::to_vec(&decoded)?;
13512	    let witness = independent_oracle_interchange(&txn, &decoded, &once, &twice, shape)?;
13513	    Ok(Case::Accepted { category, witness })
13514	}
