 14250	    reason = "evidence runner keeps deterministic accounting and digest boundaries together"
 14251	)]
 14252	fn generate_evidence(cases: u64) -> Result<(Vec<GeneratedEvidence>, Vec<u64>)> {
 14253	    validate_case_count(cases)?;
 14254	    let families: [Family; 5] = [
 14255	        ("source/CST/formatting", case_source_cst),
 14256	        ("graph/interchange codecs", case_interchange),
 14257	        ("transforms/projections", case_transform),
 14258	        ("repair/ILRP/recovery", case_repair),
 14259	        ("Basis/revision/query invalidation", case_invalidation),
 14260	    ];
 14261	
 14262	    let mut evidence = Vec::new();
 14263	    let mut timings = Vec::new();
 14264	    for (index, (family, run)) in families.into_iter().enumerate() {
 14265	        let seed = 0x9E37_79B9_7F4A_7C15_u64 ^ (index as u64).wrapping_mul(0x0100_0000_01B3);
 14266	        let mut rng = Rng(seed);
 14267	        let started = Instant::now();
 14268	        let mut digest = blake3::Hasher::new();
 14269	        digest.update(&seed.to_le_bytes());
 14270	        // ADR-0020 §4 requires >=100,000 ACCEPTED cases, so run until the
 14271	        // acceptance target is met rather than stopping at N attempts. The
 14272	        // attempt cap keeps a badly-targeted generator from running forever
 14273	        // instead of silently reporting a short campaign.
 14274	        let (mut accepted, mut discards, mut negatives, mut attempts) = (0u64, 0u64, 0u64, 0u64);
 14275	        let mut category_counts = BTreeMap::<String, u64>::new();
 14276	        // Negative categories are exercised inputs, not discards; families
 14277	        // with broad malformed coverage need a larger attempt budget to reach
 14278	        // their accepted floor without silently dropping categories.
 14279	        let attempt_cap = cases.saturating_mul(4);
 14280	        while accepted < cases {
 14281	            anyhow::ensure!(
 14282	                attempts < attempt_cap,
 14283	                "{family}: {attempts} attempts yielded only {accepted}/{cases} accepted \
 14284	                 — the generator is not targeting its declared domain"
 14285	            );
 14286	            attempts += 1;
 14287	            match run(&mut rng).with_context(|| format!("{family} attempt {attempts}"))? {
 14288	                Case::Accepted { category, witness } => {
 14289	                    // A family that witnesses nothing would restore exactly the
 14290	                    // #16 defect: a digest independent of the code under test.
 14291	                    anyhow::ensure!(
 14292	                        !witness.is_empty(),
 14293	                        "{family}: accepted attempt {attempts} with an empty witness, so \
 14294	                         the evidence hash would not depend on what the code produced"
 14295	                    );
 14296	                    accepted += 1;
 14297	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 14298	                    digest.update(b"A");
 14299	                    digest.update(category.as_bytes());
 14300	                    digest.update(&witness);
 14301	                }
 14302	                Case::Discarded { category, witness } => {
 14303	                    anyhow::ensure!(
 14304	                        !witness.is_empty(),
 14305	                        "{family}: discarded attempt {attempts} with an empty witness, so \
 14306	                         the evidence records that something was discarded and not what"
 14307	                    );
 14308	                    discards += 1;
 14309	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 14310	                    digest.update(b"D");
 14311	                    digest.update(category.as_bytes());
 14312	                    digest.update(&witness);
 14313	                }
 14314	                Case::Negative { category, witness } => {
 14315	                    anyhow::ensure!(
 14316	                        !witness.is_empty(),
 14317	                        "{family}: negative attempt {attempts} has an empty witness"
 14318	                    );
 14319	                    negatives += 1;
 14320	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 14321	                    digest.update(b"N");
 14322	                    digest.update(category.as_bytes());
 14323	                    digest.update(&witness);
 14324	                }
 14325	            }
 14326	            // The RNG state binds the INPUT; the witness above binds the OUTPUT.
 14327	            digest.update(&rng.0.to_le_bytes());
 14328	        }
 14329	        anyhow::ensure!(
 14330	            accepted + discards + negatives == attempts,
 14331	            "{family}: accounting lost cases"
 14332	        );
 14333	        let evidence_hash = digest.finalize().to_hex().to_string();
 14334	        let relation_rows = generated_relations(family)
 14335	            .iter()
 14336	            .map(|relation| GeneratedRelationEvidence {
 14337	                relation: (*relation).to_owned(),
 14338	                oracle_id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
 14339	                result: "pass".to_owned(),
 14340	                artifact_blake3: blake3::hash(
 14341	                    format!("{family}\0{relation}\0{evidence_hash}").as_bytes(),
 14342	                )
 14343	                .to_hex()
 14344	                .to_string(),
 14345	            })
 14346	            .collect::<Vec<_>>();
 14347	        let relation_matrix_blake3 = blake3::hash(
 14348	            serde_json::to_vec(&relation_rows)
 14349	                .context("serialize generated relation matrix")?
 14350	                .as_slice(),
 14351	        )
 14352	        .to_hex()
 14353	        .to_string();
 14354	        evidence.push(GeneratedEvidence {
 14355	            family: family.to_owned(),
 14356	            accepted,
 14357	            attempts,
 14358	            discards,
 14359	            negatives,
 14360	            seed,
 14361	            evidence_hash,
 14362	            category_counts,
 14363	            relations: relation_rows,
 14364	            oracle: Some(GeneratedOracleEvidence {
 14365	                id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
 14366	                source: generated_oracle_source(family).to_owned(),
 14367	                independent: true,
 14368	                relation_matrix_blake3,
 14369	            }),
 14370	        });
 14371	        timings.push(u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX));
 14372	    }
 14373	    Ok((evidence, timings))
 14374	}
