 8545	/// A requirement coordinate is an exact anchor, not a substring assertion.
 8546	///
 8547	/// Semantic anchors such as `D18.1` must not match `D18.10`; heading anchors
 8548	/// use their complete trimmed Markdown heading (`## Exit gate`) so a generic
 8549	/// word such as `exit` cannot accidentally satisfy a gate row.
 8550	fn has_exact_coordinate_anchor(source: &str, coordinate: &str) -> bool {
 8551	    let coordinate = coordinate.trim();
 8552	    if coordinate.is_empty() {
 8553	        return false;
 8554	    }
 8555	    if coordinate.starts_with("## ") {
 8556	        return source.lines().any(|line| line.trim() == coordinate);
 8557	    }
 8558	    source.lines().any(|line| {
 8559	        line.match_indices(coordinate).any(|(offset, _)| {
 8560	            let before = line[..offset].chars().next_back();
 8561	            let after = line[offset + coordinate.len()..].chars().next();
 8562	            before.is_none_or(|ch| !coordinate_anchor_char(ch))
 8563	                && after.is_none_or(|ch| !coordinate_anchor_char(ch))
 8564	        })
 8565	    })
 8566	}
