 8822	fn contains_exact_coordinate(text: &str, coordinate: &str) -> bool {
 8823	    text.match_indices(coordinate).any(|(start, _)| {
 8824	        let end = start + coordinate.len();
 8825	        !text[..start]
 8826	            .chars()
 8827	            .next_back()
 8828	            .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == ':')
 8829	            && !text[end..]
 8830	                .chars()
 8831	                .next()
 8832	                .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == ':')
 8833	    })
