 8838	/// end-to-end tests measures almost nothing, so cap any one test's share of
 8839	/// the denominator and require every named killer to exist.
 8840	fn verify_kill_concentration(packet: &Packet) -> Result<()> {
 8841	    let total = packet.mutants.len();
 8842	    if total == 0 {
 8843	        return Ok(());
 8844	    }
 8845	    let test_ids = packet
 8846	        .tests
 8847	        .iter()
 8848	        .map(|row| row.id.as_str())
 8849	        .collect::<BTreeSet<_>>();
 8850	    let mut kills = BTreeMap::<&str, usize>::new();
 8851	    for mutant in &packet.mutants {
 8852	        for test in &mutant.killing_tests {
 8853	            if !test_ids.contains(test.as_str()) {
 8854	                anyhow::bail!("{} names unknown killing test {test}", mutant.id);
 8855	            }
 8856	            *kills.entry(test.as_str()).or_default() += 1;
 8857	        }
 8858	    }
 8859	    for (test, count) in &kills {
 8860	        #[allow(clippy::cast_precision_loss, reason = "inventory-scale counts")]
 8861	        let share = *count as f64 / total as f64;
 8862	        // M17.5 F-30: `>` -> `>=` survives here and is EQUIVALENT within the
 8863	        // reachable domain. `share` is `count / total` over 65 declared
 8864	        // mutants, and 65/4 is not an integer, so `share == 0.25` exactly
 8865	        // cannot occur.
 8866	        if share > MAX_KILL_SHARE {
 8867	            anyhow::bail!(
 8868	                "{test} is the named killer for {count}/{total} mutants ({:.0}%), \
 8869	                 above the {:.0}% ceiling — mutation coverage is clustering on one \
 8870	                 coarse test",
 8871	                share * 100.0,
 8872	                MAX_KILL_SHARE * 100.0
 8873	            );
 8874	        }
 8875	    }
 8876	    Ok(())
 8877	}
