 9180	/// ADR-0020 §3's shape rules for the plan: thirteen mutants per family, no
 9181	/// operator over a quarter of the denominator, and every named operator
 9182	/// present (blind pass 1 at 5fb1b57, A04).
 9183	fn verify_mutation_plan_balance(
 9184	    by_family: &BTreeMap<&str, usize>,
 9185	    by_operator: &BTreeMap<&str, usize>,
 9186	) -> Result<()> {
 9187	    const REQUIRED_OPERATORS: [&str; 13] = [
 9188	        "predicate-deletion",
 9189	        "predicate-inversion",
 9190	        "threshold-plus-one",
 9191	        "threshold-minus-one",
 9192	        "missing-enum-dispatch",
 9193	        "success-error-substitution",
 9194	        "stale-basis-acceptance",
 9195	        "wrong-holder-selection",
 9196	        "skipped-durable-transition",
 9197	        "disabled-crash-point",
 9198	        "ordering-nondeterminism",
 9199	        "oracle-short-circuit",
 9200	        "broadened-allow-list",
 9201	    ];
 9202	    for (family, count) in by_family {
 9203	        if *count != 13 {
 9204	            anyhow::bail!("family {family} mutant count must be 13, got {count}");
 9205	        }
 9206	    }
 9207	    for (operator, count) in by_operator {
 9208	        if *count > 16 {
 9209	            anyhow::bail!("operator {operator} supplies {count} mutants; max 16");
 9210	        }
 9211	    }
