 9213	    // PRESENT, so dropping one entirely — broadened-allow-list has a single
 9214	    // mutant — left the plan short an operator ADR-0020 §3 names and nothing
 9215	    // said so. The list is the ADR's, closed.
 9216	    let missing = REQUIRED_OPERATORS
 9217	        .into_iter()
 9218	        .filter(|operator| !by_operator.contains_key(operator))
 9219	        .collect::<Vec<_>>();
 9220	    anyhow::ensure!(
 9221	        missing.is_empty(),
 9222	        "the mutation plan declares no {missing:?}; ADR-0020 §3 names every operator the plan \
 9223	         must exercise, and an absent one cannot be killed or counted"
 9224	    );
 9225	    Ok(())
 9226	}
