 9760	                .as_ref()
 9761	                .and_then(|path| path.file_name())
 9762	                .unwrap_or_default();
 9763	            if name == ".git" || name == "target" {
 9764	                continue;
 9765	            }
 9766	            let Ok(meta) = entry.path().symlink_metadata() else {
