 9872	fn anchor_supports_operator(operator: &str, anchor: &str) -> bool {
 9873	    let trimmed = anchor.trim();
 9874	    let lower = trimmed.to_ascii_lowercase();
 9875	    let chars: Vec<char> = trimmed.chars().collect();
 9876	    let negation = chars.iter().enumerate().any(|(index, ch)| {
 9877	        *ch == '!'
 9878	            && chars.get(index + 1) != Some(&'=')
 9879	            && !index
 9880	                .checked_sub(1)
 9881	                .and_then(|prev| chars.get(prev))
 9882	                .is_some_and(|prev| prev.is_alphanumeric() || *prev == '_')
 9883	    });
 9884	    let integer = chars.iter().enumerate().any(|(index, ch)| {
 9885	        ch.is_ascii_digit()
 9886	            && !index
 9887	                .checked_sub(1)
 9888	                .and_then(|prev| chars.get(prev))
 9889	                .is_some_and(|prev| prev.is_alphanumeric() || *prev == '_')
 9890	    });
 9891	    let word = |needle: &str| {
 9892	        trimmed
 9893	            .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
 9894	            .any(|token| token == needle)
 9895	    };
 9896	    match operator {
 9897	        // `|` is one of the contract's inversion pairs and must stay, but only
 9898	        // when it occurs once: a closure's `|m| ...` has two, and a generic's
 9899	        // `<` is excluded by requiring spaces, because inverting the `<` of
 9900	        // `Vec<String>` yields `Vec>=String>`, which is not a program.
 9901	        "predicate-inversion" => {
 9902	            // Blind pass 1 at `0a0b4b4b` (A04): a `|` in a PATTERN is an
 9903	            // alternative, not an operator — inverting the bar of
 9904	            // `A | B => ...` yields `A & B`, which is not a pattern and does
 9905	            // not compile, so the mutant could never be applied let alone
 9906	            // killed. A bar counts only where it can be bitwise or.
 9907	            let pattern_alternative = trimmed.contains("=>") || trimmed.starts_with('|');
 9908	            [
 9909	                "==", "!=", " <= ", " >= ", " < ", " > ", "&&", " true", " false",
 9910	            ]
 9911	            .iter()
 9912	            .any(|token| trimmed.matches(token).count() == 1)
 9913	                || has_disjunction(trimmed)
 9914	                || (!pattern_alternative && trimmed.matches('|').count() == 1)
 9915	        }
 9916	        "predicate-deletion" => negation,
 9917	        "threshold-plus-one" | "threshold-minus-one" => integer,
 9918	        "missing-enum-dispatch" => word("match"),
 9919	        "success-error-substitution" => trimmed.contains("Ok(") || trimmed.contains("Err("),
 9920	        "oracle-short-circuit" => {
 9921	            trimmed.contains("&&") || has_disjunction(trimmed) || trimmed == "if id.is_some() {"
 9922	        }
 9923	        "ordering-nondeterminism" => {
 9924	            trimmed.contains("sort")
 9925	                || trimmed.contains("BTree")
 9926	                || trimmed.starts_with("let lines: Vec<")
 9927	        }
 9928	        "stale-basis-acceptance" => {
 9929	            lower.contains("basis") || trimmed == "if rev == inner.state.head {"
 9930	        }
 9931	        "skipped-durable-transition" => DURABLE_CALL_MARKERS
 9932	            .iter()
 9933	            .any(|call| trimmed.contains(call)),
 9934	        "disabled-crash-point" => {
 9935	            lower.contains("crash")
 9936	                || trimmed == "if fail_after.is_some_and(|limit| committed >= limit) {"
 9937	        }
 9938	        "broadened-allow-list" => {
 9939	            word("match")
 9940	                || trimmed.contains("matches!")
 9941	                || trimmed.contains("ensure!")
 9942	                || trimmed.contains("=>")
 9943	        }
 9944	        "wrong-holder-selection" => WRONG_HOLDER_ANCHORS.contains(&trimmed),
 9945	        _ => false,
 9946	    }
 9947	}
