 9710	/// Every declared mutant's anchor line must be able to CARRY its operator
 9711	/// (M17.5 F-33). Runs at every layer, including stage 1a, because an
 9712	/// inapplicable mutant is a defect in the inventory, not in the evidence.
 9713	/// The locked corpus must be reachable by exactly one name (M17.5 F-34 /
 9714	/// blind pass 1 A07).
 9715	///
 9716	/// The corpus-access audit refuses a traced path containing `heldout` or
 9717	/// `conformance/corpora`. That is substring matching on what the process SAW,
 9718	/// so it catches direct access and nothing else: a symlink or a rename gives
 9719	/// the same bytes a path the filter does not recognise, and the audit reports
 9720	/// clean while the locked corpus was read.
 9721	///
 9722	/// Rather than try to canonicalize strace output after the fact — the symlink
 9723	/// may not exist by verification time — the aliasing itself is made
 9724	/// impossible. If the locked corpus has exactly one name, then matching that
 9725	/// name is sufficient, and the existing filter becomes sound rather than
 9726	/// lucky.
 9727	fn verify_locked_corpus_has_no_aliases(root: &Utf8Path) -> Result<()> {
 9728	    use std::os::unix::fs::MetadataExt as _;
 9729	    let locked = root.join("conformance/corpora/heldout");
 9730	    // M17.5 F-65: this returned Ok when the corpus was absent, and nothing
 9731	    // else in the gate required it to exist — so a tree with the corpus
 9732	    // deleted passed every corpus check vacuously while the packet went on
 9733	    // declaring `locked_acceptance_corpora_touched: false`. Twenty-three files
 9734	    // are tracked; absence is a broken tree, not an empty obligation.
 9735	    anyhow::ensure!(
 9736	        locked.is_dir(),
 9737	        "{locked} is missing: the locked corpus cannot be shown untouched when it is not there"
 9738	    );
 9739	    // The identities are the HELD-OUT corpus's, not the whole corpora tree's,
 9740	    // so a hard link from `heldout` into a sibling corpus is an alias too — it
 9741	    // would let a read of that sibling touch held-out bytes while every path
 9742	    // involved looks legitimate.
 9743	    let identities = locked_corpus_identities(root, "conformance/corpora/heldout")?;
 9744	    let canonical = fs::canonicalize(&locked)
 9745	        .with_context(|| format!("{locked}: locked corpus must resolve"))?;
 9746	    let mut aliases = Vec::new();
 9747	    let mut stack = vec![root.to_owned()];
 9748	    while let Some(dir) = stack.pop() {
 9749	        // A directory this cannot read is a directory it cannot clear of
 9750	        // aliases; the same silent skip was a hard-link bypass in F-64.
 9751	        let entries = fs::read_dir(&dir)
 9752	            .with_context(|| format!("{dir}: scan the tree for corpus aliases"))?;
 9753	        for entry in entries.flatten() {
 9754	            // Blind pass 1 at `2bba9071` (A07): this conversion failing used
 9755	            // to `continue`, so a path that is not UTF-8 skipped the identity
 9756	            // comparison — the one check that needs no path at all. It is
 9757	            // optional now; only the symlink branch requires it.
 9758	            let converted = Utf8PathBuf::from_path_buf(entry.path()).ok();
 9759	            let name = converted
 9760	                .as_ref()
 9761	                .and_then(|path| path.file_name())
 9762	                .unwrap_or_default();
 9763	            if name == ".git" || name == "target" {
 9764	                continue;
 9765	            }
 9766	            let Ok(meta) = entry.path().symlink_metadata() else {
 9767	                continue;
 9768	            };
 9769	            // Blind pass 1 at `ec045588` (A08): only symlinks counted. A hard
 9770	            // link is the alias no path reasoning sees, and one created
 9771	            // outside a traced process leaves the trace naming an innocent
 9772	            // path; if it is then removed, neither the lexical fragments nor
 9773	            // the inode check can resolve it afterwards. An alias that still
 9774	            // exists in the tree is found here, which is where it can be.
 9775	            if meta.is_file() && identities.contains(&(meta.dev(), meta.ino())) {
 9776	                // A file inside the held-out corpus is the corpus rather than
 9777	                // an alias to it. A path that is not UTF-8 cannot be inside
 9778	                // it, so it reads as outside — the conservative side.
 9779	                let inside = converted
 9780	                    .as_ref()
 9781	                    .is_some_and(|path| path.starts_with(&locked));
 9782	                if !inside {
 9783	                    aliases.push(entry.path().display().to_string());
 9784	                    continue;
 9785	                }
 9786	            }
 9787	            // The symlink branch needs the path itself; a non-UTF-8 one is
 9788	            // already covered by the identity comparison above.
 9789	            let Some(path) = converted else {
 9790	                continue;
 9791	            };
 9792	            if meta.file_type().is_symlink() {
 9793	                // A link INTO the locked tree gives its bytes a second name.
 9794	                if let Ok(resolved) = fs::canonicalize(entry.path())
 9795	                    && (resolved == canonical || resolved.starts_with(&canonical))
 9796	                    && path != locked
 9797	                {
 9798	                    aliases.push(path.to_string());
 9799	                }
 9800	            } else if meta.is_dir() {
 9801	                stack.push(path);
 9802	            }
 9803	        }
 9804	    }
 9805	    anyhow::ensure!(
 9806	        aliases.is_empty(),
 9807	        "the locked acceptance corpus is reachable under {} alias(es), so a traced \
 9808	         path can read it without naming it: {aliases:?}",
 9809	        aliases.len()
 9810	    );
 9811	    Ok(())
 9812	}
