10002	/// Require an evaluated patch to exhibit the lexical mutation prescribed by
10003	/// its closed operator.  Anchoring and compilation alone allow an unrelated
10004	/// replacement to masquerade as a predicate inversion.
10005	fn verify_mutant_operator_patch(operator: &str, patch: &MutantPatch) -> Result<()> {
10006	    let before = patch.before.as_str();
10007	    let after = patch.after.as_str();
10008	    let inversion_pairs = [
10009	        ("==", "!="),
10010	        ("!=", "=="),
10011	        ("<=", ">"),
10012	        (">=", "<"),
10013	        ("<", ">="),
10014	        (">", "<="),
10015	        ("&&", "||"),
10016	        ("||", "&&"),
10017	        ("|", "&"),
10018	        ("true", "false"),
10019	        ("false", "true"),
10020	    ];
10021	    let recognized = match operator {
10022	        "predicate-inversion" => inversion_pairs.iter().any(|(from, to)| {
10023	            before.contains(from)
10024	                && after == before.replacen(from, to, 1)
10025	                && before.matches(from).count() == 1
10026	                && after.matches(to).count() >= 1
10027	        }),
10028	        "predicate-deletion" => before.contains('!') && after == before.replacen('!', "", 1),
10029	        "threshold-plus-one" => integer_delta(before, after) == Some(1),
10030	        "threshold-minus-one" => integer_delta(before, after) == Some(-1),
10031	        "missing-enum-dispatch" => before.contains("match") && !after.contains("match"),
10032	        "success-error-substitution" => {
10033	            (before.contains("Ok(") && after.contains("Err("))
10034	                || (before.contains("Err(") && after.contains("Ok("))
10035	        }
10036	        "oracle-short-circuit" => {
10037	            ((before.contains("&&") || before.contains("||"))
10038	                && (after.contains("return") || after.contains("Ok(")))
10039	                // P1-M012's closed anchor; exact replacements only.
10040	                || (before == "if id.is_some() {"
10041	                    && matches!(after, "if true {" | "if false {"))
10042	        }
10043	        "ordering-nondeterminism" => {
10044	            ((before.contains("sort") || before.contains("BTree"))
10045	                && (!after.contains("sort") || after.contains("Hash")))
10046	                // P1-M011's closed anchor; require a Hash collection.
10047	                || (before.starts_with("let lines: Vec<")
10048	                    && before != after
10049	                    && after.contains("Hash")
10050	                    && !after.contains("let lines: Vec<"))
10051	        }
10052	        "stale-basis-acceptance" => {
10053	            (before.to_ascii_lowercase().contains("basis")
10054	                && !after.to_ascii_lowercase().contains("basis"))
10055	                || (before == "if rev == inner.state.head {"
10056	                    && matches!(after, "if true {" | "if false {"))
10057	        }
10058	        // M17.5 F-34 / blind pass 1 A11: this matched bare WORDS, so deleting
10059	        // the token from a label satisfied it. The anchored site is
10060	        // `self.commit_intent(id, intent, &format!("ack:{step_id}"), origin)?;`
10061	        // — renaming the label from `ack:` to anything else "skipped a durable
10062	        // transition" while commit_intent still ran and persistence was intact.
10063	        //
10064	        // Skipping a transition means the CALL stops happening, so the markers
10065	        // are call-shaped and the call must be gone from the after-text.
10066	        // Blind pass 1 (2026-09-05) A10/A12: P1-M022 deletes `log.append(`
10067	        // and P1-M035 deletes `.commit_if(`; neither call was on this list,
10068	        // so both mutants were unevaluable while counting toward §3.
10069	        "skipped-durable-transition" => DURABLE_CALL_MARKERS
10070	            .iter()
10071	            .any(|call| before.contains(call) && !after.contains(call)),
10072	        "disabled-crash-point" => {
10073	            (before.to_ascii_lowercase().contains("crash")
10074	                && !after.to_ascii_lowercase().contains("crash"))
10075	                // P1-M010 disables only its injected branch.
10076	                || (before == "if fail_after.is_some_and(|limit| committed >= limit) {"
10077	                    && after == "if false {")
10078	        }
10079	        "broadened-allow-list" => {
10080	            (!before.contains('*') && after.contains('*'))
10081	                // P1-M013: `matches!(byte, b'_' | b'-')` gains `| _`, admitting every byte.
10082	                || (!before.contains("| _") && after.contains("| _"))
10083	                || (!before.contains("|| true") && after.contains("|| true"))
10084	                || (before.contains("ensure!") && !after.contains("ensure!"))
10085	                // P1-M013 and P1-M026 are admitted by exact anchors below.
10086	                || (before == "if id_str.is_empty()" && after == "if false")
10087	                || (before == "match &aux.value {"
10088	                    && before != after
10089	                    && !after.contains("match")
10090	                    && after.contains("if let"))
10091	        }
10092	        "wrong-holder-selection" => {
10093	            // P1-M008: basis getter redirected to text; no generic self.*
10094	            // escape. The anchors are `WRONG_HOLDER_ANCHORS`, which
10095	            // `anchor_supports_operator` holds to as well, so a mutant cannot
10096	            // declare this operator at a line no patch here could implement.
10097	            WRONG_HOLDER_ANCHORS.contains(&before)
10098	                && ((before == "&self.basis" && after == "&self.text")
10099	                    || (before == "return Ok(inner.state.nodes.get(&id).cloned());"
10100	                        && after == "return Ok(inner.state.relations.get(&id).cloned());"))
10101	        }
10102	        _ => false,
10103	    };
10104	    anyhow::ensure!(
10105	        recognized,
10106	        "mutation patch does not implement declared operator {operator:?}"
10107	    );
10108	    Ok(())
10109	}
