10115	        let mut values = Vec::new();
10116	        let mut cursor = 0;
10117	        while let Some((index, ch)) = chars.next() {
10118	            let starts_integer = ch.is_ascii_digit()
10119	                || (ch == '-' && chars.peek().is_some_and(|(_, next)| next.is_ascii_digit()));
10120	            if !starts_integer {
10121	                continue;
10122	            }
10123	            let mut end = index + ch.len_utf8();
10124	            while let Some((next_index, next)) = chars.peek().copied() {
10125	                if !next.is_ascii_digit() {
10126	                    break;
10127	                }
10128	                chars.next();
10129	                end = next_index + next.len_utf8();
10130	            }
10480	        40..=52 => (&REPAIR, 40),
10481	        53..=65 => (&BASIS, 53),
10482	        _ => return None,
10483	    };
10484	    table.get(number - offset).copied()
