10706	/// Derive each family's fuzz minutes from the committed campaign and enforce
10707	/// ADR-0020 §4's floors against the DERIVED value (M17.5 F-17).
10708	///
10709	/// The packet says which targets belong to each family; the artifact supplies
10710	/// their seconds. Summing those rows is the sole family-budget calculation.
10711	fn verify_fuzz_budget(declared: &[Generated], recorded: &[FuzzEvidence]) -> Result<()> {
10712	    let elapsed_seconds: BTreeMap<&str, u64> = recorded
10713	        .iter()
10714	        .map(|row| (row.target.as_str(), row.elapsed_s))
10715	        .collect();
10716	    let mut total_minutes = 0_u64;
10717	    for family in declared {
10718	        if family.result != "pass" {
10719	            continue;
10720	        }
10721	        if family.fuzz_targets.is_empty() {
10722	            anyhow::bail!(
10723	                "{} claims pass but names no fuzz target; ADR-0020 §4 gives every \
10724	                 family its own sanitizer campaign, and a family with no target \
10725	                 has had none",
10726	                family.family
10727	            );
10728	        }
10729	        let mut family_minutes = 0_u64;
10730	        for target in &family.fuzz_targets {
10731	            let recorded_seconds = elapsed_seconds.get(target.as_str()).with_context(|| {
10732	                format!(
10733	                    "{} names fuzz target {target:?}, which the committed campaign did not run",
10734	                    family.family
10735	                )
10736	            })?;
10737	            family_minutes += recorded_seconds / 60;
10738	        }
10739	        // ADR-0020 line 90: one 30-minute sanitizer campaign per family.
10740	        if family_minutes < 30 {
10741	            anyhow::bail!(
10742	                "{}: its targets {:?} recorded {family_minutes} minutes, below the 30 \
10743	                 ADR-0020 §4 requires per family",
10744	                family.family,
10745	                family.fuzz_targets
10746	            );
10747	        }
10748	        total_minutes += family_minutes;
10749	    }
10750	    // ADR-0020 line 92: "Total fuzz budget is at least 150 target-minutes."
10751	    if total_minutes < 150 {
10752	        anyhow::bail!("derived fuzz budget {total_minutes} target-minutes is below 150");
